<?php
require __DIR__.'/config.php';require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$notes=trim($_POST['notes']??'');if(!$name)throw new RuntimeException('Customer name is required.');if($id)$pdo->prepare('UPDATE customers SET name=?,phone=?,address=?,notes=? WHERE id=?')->execute([$name,$phone,$address,$notes,$id]);else$pdo->prepare('INSERT INTO customers(name,phone,address,notes) VALUES(?,?,?,?)')->execute([$name,$phone,$address,$notes]);flash('Customer saved.');}elseif($action==='add_debt'){$customerId=(int)($_POST['customer_id']??0);$amount=round((float)($_POST['amount']??0),2);if($customerId<1||$amount<=0)throw new RuntimeException('Pumili ng customer at maglagay ng valid na outstanding amount.');$st=$pdo->prepare('SELECT id FROM customers WHERE id=?');$st->execute([$customerId]);if(!$st->fetch())throw new RuntimeException('Customer not found.');$receipt='JB-UTANG-'.date('ymdHis').'-'.strtoupper(bin2hex(random_bytes(2)));$pdo->prepare("INSERT INTO sales(receipt_no,customer_id,user_id,subtotal,discount,total,amount_paid,change_due,payment_method,status) VALUES(?,?,?, ?,0,?,0,0,'utang','utang')")->execute([$receipt,$customerId,current_user()['id'],$amount,$amount]);flash('Naitala ang outstanding utang.');}elseif($action==='delete'){$id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT COUNT(*) FROM sales WHERE customer_id=?');$st->execute([$id]);if((int)$st->fetchColumn()>0)throw new RuntimeException('Hindi puwedeng i-delete ang customer na may sales/utang history. I-edit na lang para mapanatili ang records.');$pdo->prepare('DELETE FROM customers WHERE id=?')->execute([$id]);flash('Customer deleted.');}elseif($action==='payment'){$saleId=(int)$_POST['sale_id'];$amount=(float)$_POST['amount'];if($amount<=0)throw new RuntimeException('Payment must be greater than zero.');$pdo->beginTransaction();$st=$pdo->prepare("SELECT total,amount_paid,status FROM sales WHERE id=? AND status<>'void' AND (status='utang' OR payment_method='utang') AND total>amount_paid FOR UPDATE");$st->execute([$saleId]);$sale=$st->fetch();if(!$sale)throw new RuntimeException('Utang sale not found.');$balance=(float)$sale['total']-(float)$sale['amount_paid'];if($amount>$balance)throw new RuntimeException('Payment exceeds the remaining balance of '.money($balance));$newPaid=(float)$sale['amount_paid']+$amount;$status=$newPaid+0.0001 >= (float)$sale['total']?'paid':'utang';$pdo->prepare('UPDATE sales SET amount_paid=?,status=? WHERE id=?')->execute([$newPaid,$status,$saleId]);$pdo->prepare('INSERT INTO debt_payments(sale_id,amount,user_id,notes) VALUES(?,?,?,?)')->execute([$saleId,$amount,current_user()['id'],trim($_POST['notes']??'Payment')]);$pdo->commit();flash('Utang payment recorded.');}}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash($ex->getMessage(),'error');}redirect('customers.php');}
$customers=$pdo->query("SELECT c.*,COALESCE((SELECT SUM(GREATEST(s.total-s.amount_paid,0)) FROM sales s WHERE s.customer_id=c.id AND s.status<>'void' AND (s.status='utang' OR s.payment_method='utang') AND s.total>s.amount_paid),0) balance FROM customers c ORDER BY c.name")->fetchAll();$debts=$pdo->query("SELECT s.*,c.name customer FROM sales s JOIN customers c ON c.id=s.customer_id WHERE s.status<>'void' AND (s.status='utang' OR s.payment_method='utang') AND s.total>s.amount_paid ORDER BY s.created_at DESC")->fetchAll();$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM customers WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$totalDebt=(float)$pdo->query("SELECT COALESCE(SUM(GREATEST(total-amount_paid,0)),0) FROM sales WHERE status<>'void' AND (status='utang' OR payment_method='utang') AND total>amount_paid")->fetchColumn();$pageTitle='Customers & Utang';require __DIR__.'/partials/header.php';?>
<div class="page-intro"><div><h1>Customers & Utang</h1><p>Keep customer records and collect outstanding balances.</p></div><span class="pill utang">Outstanding: <?=money($totalDebt)?></span></div><div class="two-col"><section class="panel"><div class="panel-heading"><div><h2><?= $edit?'Edit customer':'Add customer'?></h2><p>Customer contact details</p></div></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Full name *</label><input name="name" required value="<?=e($edit['name']??'')?>"><label>Phone</label><input name="phone" value="<?=e($edit['phone']??'')?>"><label>Address</label><input name="address" value="<?=e($edit['address']??'')?>"><label>Notes</label><textarea name="notes" rows="2"><?=e($edit['notes']??'')?></textarea><button class="btn primary">Save customer</button></form></section><section class="panel"><div class="panel-heading"><div><h2>Record existing utang</h2><p>Ilagay ang dating utang na wala sa POS transaction.</p></div></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_debt"><label>Customer *</label><select name="customer_id" required><option value="">Pumili ng customer</option><?php foreach($customers as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach;?></select><label>Outstanding amount (₱) *</label><input type="number" name="amount" min="0.01" step="0.01" placeholder="0.00" required><button class="btn primary">Save outstanding utang</button></form></section><section class="panel"><div class="panel-heading"><div><h2>Outstanding utang</h2><p>Open balances by sale</p></div></div><div class="table-wrap"><table><thead><tr><th>Customer / receipt</th><th>Balance</th><th>Collect payment</th></tr></thead><tbody><?php if(!$debts):?><tr><td colspan="3" class="empty">No outstanding utang.</td></tr><?php endif;foreach($debts as $d):$balance=$d['total']-$d['amount_paid'];?><tr><td><b><?=e($d['customer'])?></b><small><?=e($d['receipt_no'])?> · <?=date('M j, Y',strtotime($d['created_at']))?></small></td><td><?=money($balance)?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="payment"><input type="hidden" name="sale_id" value="<?=$d['id']?>"><input type="number" name="amount" min=".01" max="<?=e($balance)?>" step=".01" placeholder="₱ amount" required><button class="btn secondary compact">Collect</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><section class="panel section-gap"><div class="panel-heading"><div><h2>Customer directory</h2><p><?=count($customers)?> customers</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Address</th><th>Outstanding balance</th><th>Action</th></tr></thead><tbody><?php if(!$customers):?><tr><td colspan="5" class="empty">No customers added yet.</td></tr><?php endif;foreach($customers as $c):?><tr><td><b><?=e($c['name'])?></b></td><td><?=e($c['phone']?:'—')?></td><td><?=e($c['address']?:'—')?></td><td><?=money($c['balance'])?></td><td><a href="customers.php?edit=<?=$c['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('I-delete ang customer? Hindi ito papayagan kung may sales/utang history.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($c['id'])?>"><button class="btn secondary compact" type="submit">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php';?>